import { brand } from "../components/ui.js";
import { money, esc, imageSrc, whatsapp } from "../utils/format.js";
export function home(db) {
  const s = db.settings,
    services = db.services.filter((x) => x.active);
  return `<div class="announcement">Um espaço para realçar a sua beleza em todos os detalhes.</div><header class="public-header">${brand(s)}<nav aria-label="Principal"><a href="#sobre">O espaço</a><a href="#servicos">Serviços & valores</a><a href="#galeria">Nosso trabalho</a><a href="#contato">Contato</a></nav><a class="button small" href="/agendar">Agendar horário</a></header><main>
<section class="hero"><div class="hero-copy"><p class="eyebrow"><span></span> CUIDADO QUE VAI ALÉM DA BELEZA</p><h1>Seu momento.<br>Sua beleza.<br><em>Em cada detalhe.</em></h1><p>Mais do que unhas bem cuidadas. Um tempo só seu, em um espaço feito para você se sentir especial.</p><div class="hero-actions"><a class="button" href="/agendar">Agendar meu momento</a><a class="text-link" href="#servicos">Conheça os serviços</a></div><div class="hero-note"><span class="mini-monogram">JC</span><div>Beleza, cuidado e excelência<small>Unhas naturais e artificiais · Osasco, SP</small></div></div></div><div class="hero-photo"><img src="/assets/espaco.png" alt="Jéssica Campos no ambiente acolhedor do salão"><div class="photo-caption"><span>${esc(s.name).toUpperCase()}</span><i>Embelezar com propósito.</i></div></div><span class="hero-side">CUIDADO · QUALIDADE · CONFIANÇA</span></section>
<div class="values-strip"><span>Especialista em unhas</span><b>✧</b><span>Beleza com naturalidade</span><b>✧</b><span>Cuidado individualizado</span><b>✧</b><span>Um momento para você</span></div>
<section id="servicos" class="section"><div class="section-heading"><div><p class="eyebrow">SERVIÇOS & VALORES</p><h2>Pequenos cuidados.<br><em>Uma nova forma de se sentir.</em></h2></div><p>Encontre o cuidado que combina com você.<br><small>Valores iniciais de demonstração, editáveis no painel.</small></p></div><div class="services-grid">${services.map((x, i) => `<article class="service-card"><div class="service-number">0${i + 1}<span>✧</span></div><p class="eyebrow">${esc(x.category)}</p><h3>${esc(x.name)}</h3><p>${esc(x.description)}</p><div class="service-bottom"><span><strong>${money(x.price)}</strong><small>${x.duration} minutos</small></span><a href="/agendar?servico=${x.id}" class="circle-link" aria-label="Agendar ${esc(x.name)}">+</a></div></article>`).join("")}</div></section>
<section id="sobre" class="about section"><div class="about-photo"><img src="/assets/jessica.png" alt="Jéssica Campos, à frente do Espaço Jeh Campus" loading="lazy"><span>Beleza com propósito, sempre.</span></div><div class="about-copy"><p class="eyebrow">BEM-VINDA AO NOSSO ESPAÇO</p><h2>Você merece cuidado.<br><em>Em todos os sentidos.</em></h2><p>Sou Jéssica Campos, e acredito que a beleza está nos detalhes — e também em como você se sente.</p><p>No ${esc(s.name)}, cada atendimento é um convite para desacelerar. Um ambiente acolhedor, um olhar atento e um cuidado pensado para valorizar o que faz você ser única.</p><div class="signature">Jéssica Campos</div><small>FUNDADORA · ${esc(s.name).toUpperCase()}</small><a class="text-link" href="/agendar">Reserve um tempo para você</a></div></section>
<section id="galeria" class="section gallery-section"><div class="section-heading"><div><p class="eyebrow">BELEZA QUE SE VÊ. CUIDADO QUE SE SENTE.</p><h2>Detalhes que <em>encantam.</em></h2></div><a class="text-link" href="https://www.instagram.com/${encodeURIComponent(s.instagram)}/" target="_blank" rel="noopener">@${esc(s.instagram)}</a></div><div class="gallery-grid">${db.gallery.map((g) => `<figure><button data-photo="${g.id}" aria-label="Ampliar: ${esc(g.description)}"><img src="${imageSrc(g.image)}" alt="${esc(g.description)}" loading="lazy"></button><figcaption><small>${esc(g.category)}</small><h3>${esc(g.description)}</h3></figcaption></figure>`).join("")}</div></section>
<section class="difference section"><p class="eyebrow">A EXPERIÊNCIA JEH CAMPUS</p><h2>O cuidado está <em>em tudo.</em></h2><div class="three-columns"><article><span>01 /</span><h3>Olhar para você</h3><p>Atendimento individual, respeitando seu estilo e o seu tempo.</p></article><article><span>02 /</span><h3>Carinho nos detalhes</h3><p>Do acolhimento ao acabamento, cada etapa recebe atenção.</p></article><article><span>03 /</span><h3>Beleza com leveza</h3><p>Um ambiente tranquilo para transformar cuidado em bem-estar.</p></article></div></section>
<section class="reviews section"><p class="eyebrow">AVALIAÇÕES</p><h2>Seu carinho também<br><em>faz parte do nosso espaço.</em></h2><p>Já viveu essa experiência? Compartilhe sua opinião com a gente no Instagram.</p><a class="text-link" href="https://www.instagram.com/${encodeURIComponent(s.instagram)}/" target="_blank" rel="noopener">Visite nosso Instagram</a></section>
<section id="contato" class="contact section"><div><p class="eyebrow">VAMOS NOS ENCONTRAR?</p><h2>Seu próximo momento<br><em>de cuidado começa aqui.</em></h2><a href="/agendar" class="button">Agendar horário</a></div><div class="contact-info"><h3>${esc(s.name)}</h3><p>${esc(s.address)}</p><a class="text-link" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(s.address)}" target="_blank" rel="noopener">Como chegar</a><div class="hours">${s.hours
    .filter((x) => x.open)
    .map(
      (h) =>
        `<span>${["Domingo", "Segunda", "Terça", "Quarta", "Quinta", "Sexta", "Sábado"][h.day]} <b>${h.start} – ${h.end}</b></span>`,
    )
    .join(
      "",
    )}</div>${s.whatsapp ? `<a class="text-link" href="https://wa.me/${whatsapp(s.whatsapp)}" target="_blank" rel="noopener">Converse pelo WhatsApp</a>` : '<p class="muted">Contato pelo Instagram</p>'}${s.phone ? `<a href="tel:${whatsapp(s.phone)}">${esc(s.phone)}</a>` : ""}</div></section></main><footer>${brand(s)}<p>Beleza, cuidado e excelência em cada detalhe.</p><a href="/admin">Área administrativa</a><small>© ${new Date().getFullYear()} ${esc(s.name)}</small></footer><a class="mobile-book button" href="/agendar">Agendar horário</a>`;
}
